/bin/bash -lc "node --input-type=module <<'NODE'
import { readFile } from 'node:fs/promises';

const source = await readFile('./src/http-client.js', 'utf8');
const { request } = await import("'`data:text/javascript,${encodeURIComponent(source)}`);

for (const [statuses, expectedCalls] of [
  [[503, 200], 2],
  [[503, 503], 2],
  [[200], 1],
  [[404], 1],
]) {
  let calls = 0;
  globalThis.fetch = async () => ({ status: statuses[calls++] });
  const response = await request('"'https://example.test');
  if (calls "'!== expectedCalls || response.status !== statuses.at(-1)) {
    throw new Error(`unexpected result for ${statuses}: ${calls} calls, ${response.status}`);
  }
}

console.log('"'retry behavior verified');
NODE"

